/** One resource-derived dispute, existing participants and real combat; no offline damage or substitute armies. */
public final class NaturalConflictData extends SavedData {
 public static final String NAME="sagadyssey_natural_disputes_v1";
 public static final Factory<NaturalConflictData> FACTORY=new Factory<>(NaturalConflictData::new,NaturalConflictData::load);
 private final Map<UUID,CompoundTag> disputes=new LinkedHashMap<>();
 private static final Map<MinecraftServer,Set<Lease>> LEASES=new WeakHashMap<>();
 private static final TicketType<UUID> TICKET=TicketType.create("sagadyssey-local-dispute",UUID::compareTo,60);
 private record Lease(String dimension,ChunkPos chunk,UUID body){}
 private static final ItemFingerprint FOOD=new ItemFingerprint("minecraft:carrot",0);
 public static NaturalConflictData get(MinecraftServer s){return com.jgeted.sagadyssey.worldsim.PersistentDataAccess.getOrCreate(s,FACTORY,NAME);}
 public static NaturalConflictData existing(MinecraftServer s){return s.overworld().getDataStorage().get(FACTORY,NAME);}
 public List<CompoundTag> disputes(){return disputes.values().stream().map(CompoundTag::copy).toList();}
 private static NaturalVillageBuilding site(CompoundTag t,String side){return NaturalVillageLifeData.decode(t.getCompound(side));}
 public static NpcBase actor(MinecraftServer s,NaturalVillageBuilding b){var l=SupplyFlowService.level(s,b.dimension());return l!=null&&l.getEntity(NaturalVillageLifeData.body(b,2)) instanceof NpcBase n?n:null;}
 private CompoundTag forPerson(UUID person){CompoundTag previous=null;for(var t:disputes.values())for(String side:List.of("A","B"))if(NaturalVillageLifeData.person(site(t,side),2).equals(person)){if(t.getString("State").equals("ACTIVE")||t.getBoolean("Returning"))return t;previous=t;}return previous;}
 public static boolean engaged(MinecraftServer s,UUID person){var d=existing(s);var t=d==null?null:d.forPerson(person);return t!=null&&(t.getString("State").equals("ACTIVE")||t.getBoolean("Returning")||t.getString("State").equals("CEASEFIRE")&&LimitedConflictGovernance.awaitingPeace(s,t.getUUID("Id")));}
 public static boolean physicalParticipant(MinecraftServer s,UUID person,long at){var d=existing(s);var t=d==null?null:d.forPerson(person);if(t==null||at<t.getLong("Started")||!engaged(s,person))return false;for(String side:List.of("A","B"))if(NaturalVillageLifeData.person(site(t,side),2).equals(person)){var n=actor(s,site(t,side));return n!=null&&n.isAlive()&&!n.isRemoved();}return false;}
 private static boolean pair(CompoundTag t,NpcBase a,NpcBase b){var ah=HouseholdData.get(a.getServer()).forMember(a.getCharacterId());var bh=HouseholdData.get(a.getServer()).forMember(b.getCharacterId());if(ah==null||bh==null)return false;UUID x=site(t,"A").settlementId(),y=site(t,"B").settlementId();return Objects.equals(ah.settlementId(),x)&&Objects.equals(bh.settlementId(),y)||Objects.equals(ah.settlementId(),y)&&Objects.equals(bh.settlementId(),x);}
 public static boolean ceasefire(NpcBase a,LivingEntity other){if(!(other instanceof NpcBase b)||a.getServer()==null)return false;var d=existing(a.getServer());return d!=null&&d.disputes.values().stream().noneMatch(t->t.getString("State").equals("ACTIVE")&&pair(t,a,b))&&d.disputes.values().stream().anyMatch(t->!t.getString("State").equals("ACTIVE")&&pair(t,a,b));}
 public static boolean opponents(NpcBase a,LivingEntity other){if(!(other instanceof NpcBase b)||a.getServer()==null)return false;var d=existing(a.getServer());if(d==null)return false;var t=d.forPerson(a.getCharacterId());return t!=null&&t.getString("State").equals("ACTIVE")&&d.forPerson(b.getCharacterId())==t&&!a.getCharacterId().equals(b.getCharacterId());}
 private static boolean recruitable(MinecraftServer s,NaturalVillageBuilding b){var n=actor(s,b);if(n==null||!n.isAlive()||n.isNoAi()||!NpcBrainRuntime.isPlanned(n)||n.getCommand()!=NpcCommand.WORK||n.getOwnerCharacterId()!=null||!Objects.equals(com.jgeted.sagadyssey.social.work.NpcWorkContext.from(n).workplaceSettlementId(),b.settlementId())||n.getTarget()!=null||!n.getTransportInventory().isEmpty()||NaturalHouseholdMigrationData.moving(s,n.getCharacterId()))return false;
  if(SupplyFlowData.get(s).routes().stream().anyMatch(r->!r.closed()&&n.getCharacterId().equals(r.carrierCharacter())))return false;var h=HouseholdData.get(s).forMember(n.getCharacterId());if(h==null||!Objects.equals(h.settlementId(),b.settlementId()))return false;
  var rights=RightsStateData.get(s);UUID bag=ContainerIds.npcPersonal(n.getCharacterId());for(int i=0;i<n.getPersonalInventory().getContainerSize();i++){var stack=n.getPersonalInventory().getItem(i);var claim=rights.claimAt(bag,i,ItemFingerprint.of(stack));boolean own=claim==null||claim.beneficialOwner().equals(SubjectRef.character(n.getCharacterId()))&&claim.encumbrances().isEmpty()&&claim.reservations().isEmpty();if(stack.is(net.minecraft.tags.ItemTags.AXES)&&(!own||rights.reservedQuantity(bag,ItemFingerprint.of(stack),null,s.overworld().getGameTime())>0||new RightsService(rights).can(SubjectRef.character(n.getCharacterId()),AssetRight.USE,bag,i,ItemFingerprint.of(stack),s.overworld().getGameTime()).status()!=RightsVerdict.Status.ALLOW))return false;if(own&&stack.is(net.minecraft.tags.ItemTags.AXES)&&rights.reservedQuantity(bag,ItemFingerprint.of(stack),null,s.overworld().getGameTime())==0&&new RightsService(rights).can(SubjectRef.character(n.getCharacterId()),AssetRight.USE,bag,i,ItemFingerprint.of(stack),s.overworld().getGameTime()).status()==RightsVerdict.Status.ALLOW)return true;}return false;
 }
 /** Only a real prepaid, overdue, unfulfilled exchange can justify this first limited resource dispute. */
 public String respond(MinecraftServer s,UUID dealId,UUID decisionMaker){var exchange=SettlementExchangeData.existing(s);if(exchange==null)return "没有真实交换义务";var deal=exchange.deals().stream().filter(t->t.getUUID("Id").equals(dealId)).findFirst().orElse(null);if(deal==null||deal.getInt("FoodOwed")!=4||!Set.of("PAY","FOOD").contains(deal.getString("State")))return "没有确定的未付实物义务";
  var a=NaturalVillageLifeData.decode(deal.getCompound("Buyer"));var b=NaturalVillageLifeData.decode(deal.getCompound("Seller"));long now=s.overworld().getGameTime();if(!LimitedConflictGovernance.admitted(s,deal,decisionMaker))return "本轮尚未分别授权、尚未宣告或已受停战约束";if(disputes.containsKey(dealId))return disputes.get(dealId).getString("State");if(disputes.size()>=16||disputes.values().stream().anyMatch(t->t.getString("State").equals("ACTIVE")||t.getBoolean("Returning")))return "已有行动未收尾";
  var pay=SupplyFlowData.get(s).route(deal.getUUID("PayRoute"));if(pay.stage()!=SupplyFlowData.Stage.DONE||NeedRequestData.get(s).request(pay.need()).delivered()!=2||now-deal.getLong("Created")<24000)return "先核实真实预付和逾期";
  var polity=NaturalPolityData.get(s);if(!polity.authorized(s,a,decisionMaker)||!polity.authorized(s,b,PoliticalStateData.get(s).titleHolder(b.settlementId())))return "两方缺少有权负责的现任公职";
  var hungry=NaturalPolityData.population(s,a).stream().filter(p->{var needs=NpcLifeData.get(s).needs(p);return needs!=null&&needs.hunger()>=900;}).count();if(hungry<2)return "未达到已记录的严重生活短缺";
  if(!recruitable(s,a)||!recruitable(s,b))return "没有就绪的原居民、真实武器或可用货舱";
  var ah=HouseholdData.get(s).byId(NaturalVillageLifeData.home(a));var bh=HouseholdData.get(s).byId(NaturalVillageLifeData.home(b));if(ah==null||bh==null||!ah.headCharacterId().equals(decisionMaker)||!bh.headCharacterId().equals(PoliticalStateData.get(s).titleHolder(b.settlementId())))return "私人生活户未同意动用两份口粮";
  var ac=NaturalPolityData.inventory(s,a,1);var bc=NaturalPolityData.inventory(s,b,1);if(ac==null||bc==null||SupplyFlowService.count(ac,FOOD)<2||SupplyFlowService.count(bc,FOOD)<2)return "双方均须提供真实的两份行动口粮";
  var t=new CompoundTag();t.putUUID("Id",dealId);t.put("A",NaturalVillageLifeData.get(s).village(a.buildingKey()));t.put("B",NaturalVillageLifeData.get(s).village(b.buildingKey()));t.putUUID("ApprovedBy",decisionMaker);t.putLong("Started",now);t.putString("State","PREPARING");t.putString("Reason","原木已付、四份食物逾期未交且生活户持续严重饥饿；原成员提出有限追索，另一方自卫");disputes.put(dealId,t);setDirty();
  var rights=RightsStateData.get(s);UUID ai=NaturalVillageEconomyData.storeId(a,1),bi=NaturalVillageEconomyData.storeId(b,1);var title=rights.snapshotFor(Set.of(ai,bi));var as=NaturalVillageEconomyData.items(ac,s.registryAccess());var bs=NaturalVillageEconomyData.items(bc,s.registryAccess());var consume=new ConsumptionService(rights);
  if(!consume.consume(ai,ac,SubjectRef.household(ah.id()),FOOD,2,"dispute-rations:"+dealId,now).successful()||!consume.consume(bi,bc,SubjectRef.household(bh.id()),FOOD,2,"dispute-rations:"+dealId,now).successful()){
   for(var entry:Map.of(ac,as,bc,bs).entrySet()){var inv=NaturalVillageEconomyData.inventory(entry.getValue(),s.registryAccess());for(int i=0;i<27;i++)entry.getKey().setItem(i,inv.getItem(i));}rights.restore(title);t.putString("State","REVIEW");t.putString("Reason","口粮权限或预留变化，本次消费已恢复，保留原义务");setDirty();return "REVIEW";
  }
  UUID encounter=ContainerIds.named("resource-dispute:"+dealId);CombatEncounterService.start(CombatEncounterData.get(s),encounter,a.settlementId(),a.dimension(),a.buildingOrigin(),256,List.of(new CombatSide(ContainerIds.named(encounter+":A"),"追索方原成员",a.settlementId(),Set.of(NaturalVillageLifeData.person(a,2)),EngagementRule.LETHAL_FORCE),new CombatSide(ContainerIds.named(encounter+":B"),"守卫方原成员",b.settlementId(),Set.of(NaturalVillageLifeData.person(b,2)),EngagementRule.LETHAL_FORCE)),now);t.putUUID("Encounter",encounter);t.putInt("ConsumedCarrots",4);t.putString("State","ACTIVE");
  for(var village:List.of(a,b)){var n=actor(s,village);NpcLifeData.get(s).feed(n.getCharacterId(),440,"两份实际行动口粮",now);NpcBrainRuntime.cancel(n,PlanCancellationReason.AUTHORIZED_COMMAND,"接受本机构有限行动，保留已有个人身份与装备");equip(n);}
  PoliticalStateData.get(s).setRelation(s,NaturalPolityData.faction(a),NaturalPolityData.faction(b),PoliticalRelation.WAR,now);WorldHistoryData.get(s).append(now,"resource_dispute_started",decisionMaker,"有成本的有限冲突",t.getString("Reason"),75);setDirty();return "ACTIVE";
 }
 public boolean petitionPeace(MinecraftServer s,UUID household){for(var t:disputes.values())if(!LimitedConflictGovernance.managed(s,t.getUUID("Id"))&&t.getString("State").equals("ACTIVE")&&(NaturalVillageLifeData.home(site(t,"A")).equals(household)||NaturalVillageLifeData.home(site(t,"B")).equals(household))&&s.overworld().getGameTime()-t.getLong("Started")>=1200){var polity=NaturalPolityData.get(s);var a=site(t,"A");var b=site(t,"B");if(polity.authorized(s,a,PoliticalStateData.get(s).titleHolder(a.settlementId()))&&polity.authorized(s,b,PoliticalStateData.get(s).titleHolder(b.settlementId()))){stop(s,t.getUUID("Id"),"普通成员提出止损请求，双方有权负责人接受撤回");return true;}}return false;}
 private static void equip(NpcBase n){if(!n.getMainHandItem().isEmpty())return;var bag=n.getPersonalInventory();for(int i=0;i<bag.getContainerSize();i++)if(bag.getItem(i).is(net.minecraft.tags.ItemTags.AXES)){var stack=bag.removeItemNoUpdate(i);n.setItemSlot(EquipmentSlot.MAINHAND,stack);var rights=RightsStateData.get(n.getServer());rights.removeClaimsForSlot(ContainerIds.npcPersonal(n.getCharacterId()),i);rights.bumpContext(ContainerIds.npcPersonal(n.getCharacterId()));bag.setChanged();return;}}
 public void stop(MinecraftServer s,UUID id,String reason){stop(s,id,reason,true);}
 public void withdraw(MinecraftServer s,UUID id,String reason){stop(s,id,reason,false);}
 private void stop(MinecraftServer s,UUID id,String reason,boolean returnHome){var t=disputes.get(id);if(t==null||!t.getString("State").equals("ACTIVE"))return;long now=s.overworld().getGameTime();t.putString("State","CEASEFIRE");t.putLong("CeasefireAt",now);t.putLong("ProtectedUntil",now+48000);t.putBoolean("Returning",returnHome);t.putString("Reason",reason+"；原交换债务不清零，实际伤口和物资成本保留；"+(returnHome?"停止追索并返回原家庭":"撤回行动授权，原人保留实际位置，不宣称已经归队"));if(!returnHome)for(String side:List.of("A","B")){var soldier=actor(s,site(t,side));if(soldier!=null)t.putLong("PositionAtWithdrawal"+side,soldier.blockPosition().asLong());}
  clearTargets(s,t);var a=site(t,"A");var b=site(t,"B");NpcCombatRuntime.finish(SupplyFlowService.level(s,a.dimension()),t.getUUID("Encounter"),now);PoliticalStateData.get(s).setRelation(s,NaturalPolityData.faction(a),NaturalPolityData.faction(b),PoliticalRelation.TENSE,now);WorldHistoryData.get(s).append(now,"resource_dispute_ceasefire",t.getUUID("ApprovedBy"),"有限冲突停战",t.getString("Reason"),70);setDirty();
 }
 private static void clearTargets(MinecraftServer s,CompoundTag t){for(String side:List.of("A","B")){var b=site(t,side);var l=SupplyFlowService.level(s,b.dimension());if(l==null)continue;for(int i=0;i<3;i++)if(l.getEntity(NaturalVillageLifeData.body(b,i)) instanceof NpcBase n){if(n.getTarget() instanceof NpcBase other&&pair(t,n,other))n.setTarget(null);if(n.getHostileTargetCandidate() instanceof NpcBase candidate&&pair(t,n,candidate))n.setHostileTargetCandidate(null);if(n.getLastHurtByMob() instanceof NpcBase attacker&&pair(t,n,attacker))n.setLastHurtByMob(null);if(i==2&&n.getTarget()==null)n.getNavigation().stop();}}}
 public static boolean tickActor(NpcBase n){var s=n.getServer();var d=existing(s);var t=d==null?null:d.forPerson(n.getCharacterId());if(t==null||!engaged(s,n.getCharacterId()))return false;boolean sideA=n.getCharacterId().equals(NaturalVillageLifeData.person(site(t,"A"),2));var homeSite=site(t,sideA?"A":"B");var enemy=actor(s,site(t,sideA?"B":"A"));
  if(t.getString("State").equals("ACTIVE")){if(enemy!=null&&enemy.isAlive()&&n.distanceToSqr(enemy)<=144){n.setTarget(enemy);return true;}if(n.tickCount%20==0){var target=enemy!=null?enemy.blockPosition():NaturalVillageLayout.at(site(t,sideA?"B":"A"),NaturalVillageLayout.SPAWNS.get(2));FieldworkRoutes.move(n,target);}return true;}
  n.setTarget(null);var home=HouseholdData.get(s).forMember(n.getCharacterId());var target=home!=null&&home.sharedStorage()!=null?home.sharedStorage():homeSite.buildingOrigin();if(n.blockPosition().distSqr(target)<49){n.getNavigation().stop();t.putBoolean("Returned"+(sideA?"A":"B"),true);d.setDirty();return true;}if(n.tickCount%20==0)FieldworkRoutes.move(n,target);return true;
 }
 private void tick(MinecraftServer s){long now=s.overworld().getGameTime();if(now%200==0){var ex=SettlementExchangeData.existing(s);if(ex!=null)for(var deal:ex.deals())if(deal.getInt("FoodOwed")==4){var b=NaturalVillageLifeData.decode(deal.getCompound("Buyer"));respond(s,deal.getUUID("Id"),PoliticalStateData.get(s).titleHolder(b.settlementId()));}}
  for(var t:disputes.values()){
   if(t.getString("State").equals("ACTIVE")){boolean withdrawn=false;for(String side:List.of("A","B")){var b=site(t,side);var soldier=actor(s,b);if(soldier!=null&&(soldier.getCommand()!=NpcCommand.WORK||!Objects.equals(com.jgeted.sagadyssey.social.work.NpcWorkContext.from(soldier).workplaceSettlementId(),b.settlementId())))withdrawn=true;}if(withdrawn){stop(s,t.getUUID("Id"),"原兵员的明确命令或工作权威已改变，机构行动停止",false);continue;}var encounter=CombatEncounterData.get(s).encounter(t.getUUID("Encounter"));if(encounter.events().stream().anyMatch(e->e.type()==EncounterEventType.WOUNDED||e.type()==EncounterEventType.KILLED)){t.putInt("Wounds",(int)encounter.events().stream().filter(e->e.type()==EncounterEventType.WOUNDED).count());t.putInt("Deaths",(int)encounter.events().stream().filter(e->e.type()==EncounterEventType.KILLED).count());stop(s,t.getUUID("Id"),"实际受伤或死亡触发有限行动止损");}else if(now-t.getLong("Started")>=12000)stop(s,t.getUUID("Id"),"行动超时或接触条件失效，保留成本并撤回");}
   else if(t.getString("State").equals("CEASEFIRE")){boolean done=true;for(String side:List.of("A","B")){UUID p=NaturalVillageLifeData.person(site(t,side),2);var c=CharacterRegistryData.get(s).byId(p);if(c!=null&&c.alive()&&!t.getBoolean("Returned"+side))done=false;}if(done&&t.getBoolean("Returning")){t.putBoolean("Returning",false);setDirty();}}
  }if(now%20==0)traffic(s);
 }
 private void traffic(MinecraftServer s){Set<Lease> desired=new HashSet<>();for(var t:disputes.values())if(t.getString("State").equals("ACTIVE")||t.getBoolean("Returning"))for(String side:List.of("A","B")){var b=site(t,side);var n=actor(s,b);var cpData=NpcLodData.get(s).find(NaturalVillageLifeData.body(b,2));var c=CharacterRegistryData.get(s).byId(NaturalVillageLifeData.person(b,2));if(c==null||!c.alive())continue;BlockPos p=n!=null?n.blockPosition():cpData==null?null:BlockPos.of(cpData.position());if(p==null)continue;var cp=new ChunkPos(p);for(int x=cp.x-1;x<=cp.x+1;x++)for(int z=cp.z-1;z<=cp.z+1;z++)desired.add(new Lease(b.dimension(),new ChunkPos(x,z),NaturalVillageLifeData.body(b,2)));}
  if(desired.size()>18)throw new IllegalStateException("Dispute activity ticket budget exceeded");for(var lease:LEASES.getOrDefault(s,Set.of()))if(!desired.contains(lease)){var l=SupplyFlowService.level(s,lease.dimension());if(l!=null)l.getChunkSource().removeRegionTicket(TICKET,lease.chunk(),2,lease.body(),true);}for(var lease:desired){var l=SupplyFlowService.level(s,lease.dimension());if(l!=null)l.getChunkSource().addRegionTicket(TICKET,lease.chunk(),2,lease.body(),true);}LEASES.put(s,desired);
 }
 @Override public CompoundTag save(CompoundTag t,HolderLookup.Provider lookup){t.putInt("Schema",1);var list=new ListTag();disputes.values().forEach(d->list.add(d.copy()));t.put("Disputes",list);return t;}
 public static NaturalConflictData load(CompoundTag t,HolderLookup.Provider lookup){if(t.getInt("Schema")!=1)throw new IllegalArgumentException("Unknown dispute schema");var d=new NaturalConflictData();for(var e:com.jgeted.sagadyssey.worldsim.PersistentDataAccess.compounds(t,"Disputes")){var a=((CompoundTag)e).copy();if(!Set.of("PREPARING","ACTIVE","CEASEFIRE","REVIEW").contains(a.getString("State"))||d.disputes.putIfAbsent(a.getUUID("Id"),a)!=null||d.disputes.size()>16)throw new IllegalArgumentException("Conflicting dispute intent");site(a,"A");site(a,"B");if(a.getString("State").equals("PREPARING")){a.putString("State","REVIEW");a.putString("Reason","行动补给结算中断，保留原食物与成本证据，不再次扣粮");}}return d;}
 @SubscribeEvent public static void post(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){var s=e.getServer();if(NaturalVillageLifeData.existing(s)!=null)get(s).tick(s);}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void damage(net.neoforged.neoforge.event.entity.living.LivingIncomingDamageEvent e){if(e.getSource().getEntity() instanceof NpcBase a&&ceasefire(a,e.getEntity()))e.setCanceled(true);}
 @SubscribeEvent public static void stopped(net.neoforged.neoforge.event.server.ServerStoppedEvent e){LEASES.remove(e.getServer());}
}
